    call hbc_print_str
.Ltrace_skip:
    mov (%r12), %r12
    test %r12, %r12
    jnz .Ltrace_next
.Ltrace_done:
    add $40, %rsp
    pop %r12
    pop %rbp
    ret
# Error labels may jump here with arbitrary helper frames and alignment.
